import { useState } from 'react'
import {
  PageContainer,
  ProCard
} from '@ant-design/pro-components'
import {
  Button,
  message,
  Space,
  Card,
  Form,
  Switch,
  Checkbox,
  Input,
  Row,
  Col,
  Tooltip
} from 'antd'
import {
  SaveOutlined,
  BellOutlined,
  BoxPlotOutlined,
  GiftOutlined,
  WarningOutlined,
  UserOutlined,
  InboxOutlined,
  ClockCircleOutlined,
  FileTextOutlined,
  InfoCircleOutlined,
  CheckCircleOutlined,
  QuestionCircleOutlined
} from '@ant-design/icons'

const { TextArea } = Input

interface NotificationConfig {
  enabled: boolean
  channels: {
    sms: boolean
    wechat: boolean
    both: boolean
  }
  template: string
}

interface NotificationSettings {
  depositSuccess: NotificationConfig
  pickupReminder: NotificationConfig
  overdueReminder: NotificationConfig
  retentionReminder: NotificationConfig
  deviceAlarm: NotificationConfig
  authResult: NotificationConfig
  pointsCredit: NotificationConfig
  pointsExpire: NotificationConfig
}

const Notification: React.FC = () => {
  const [form] = Form.useForm()
  const [saving, setSaving] = useState(false)

  // 初始配置值
  const initialValues: NotificationSettings = {
    depositSuccess: {
      enabled: true,
      channels: { sms: true, wechat: true, both: false },
      template: '您好，您的物品已成功存入{设备名称}{格口编号}，取件码为{取件码}，请在{有效期}内凭取件码取件。'
    },
    pickupReminder: {
      enabled: true,
      channels: { sms: false, wechat: true, both: false },
      template: '您好，您在{设备名称}{格口编号}存放的物品已存放{存放时长}，请尽快取件，超时将产生额外费用。'
    },
    overdueReminder: {
      enabled: true,
      channels: { sms: true, wechat: true, both: true },
      template: '您好，您存放在{设备名称}{格口编号}的物品已超期{超期天数}天，请尽快取件。当前超期费用为¥{超期费用}，每日将额外收取¥{日费用}。'
    },
    retentionReminder: {
      enabled: true,
      channels: { sms: true, wechat: true, both: false },
      template: '提醒：您存放在{设备名称}{格口编号}的物品已滞留{滞留天数}天，请尽快取件。如长时间未取，系统将进行相应处理。'
    },
    deviceAlarm: {
      enabled: true,
      channels: { sms: true, wechat: false, both: false },
      template: '【设备告警】{设备名称}（{设备编号}）发生{告警类型}，告警详情：{告警内容}，请及时处理。'
    },
    authResult: {
      enabled: true,
      channels: { sms: false, wechat: true, both: false },
      template: '您好，您的{认证类型}认证申请{审核结果}。{驳回原因}'
    },
    pointsCredit: {
      enabled: true,
      channels: { sms: true, wechat: true, both: false },
      template: '您好，您已获得{积分数量}积分（来源：{积分来源}），当前积分余额为{积分余额}，可用于商品消费抵扣。'
    },
    pointsExpire: {
      enabled: true,
      channels: { sms: true, wechat: false, both: false },
      template: '提醒：您有{即将过期积分}积分将于{过期时间}失效，请尽快使用。当前积分余额：{积分余额}。'
    }
  }

  // 保存配置
  const handleSave = async () => {
    try {
      const values = await form.validateFields()
      setSaving(true)

      // 这里应该调用保存接口
      console.log('保存通知配置:', values)

      // 模拟保存
      setTimeout(() => {
        message.success('通知配置已保存')
        setSaving(false)
      }, 500)
    } catch (e) {
      console.error(e)
      setSaving(false)
    }
  }

  // 通知配置项组件
  const NotificationItem = ({
    name,
    icon,
    title,
    color,
    description
  }: {
    name: string
    icon: React.ReactNode
    title: string
    color: string
    description?: string
  }) => (
    <Card
      style={{ marginBottom: 16 }}
      bodyStyle={{ padding: 20 }}
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        {/* 头部 */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Space>
            <span style={{ color, fontSize: 18 }}>{icon}</span>
            <span style={{ fontSize: 16, fontWeight: 500 }}>{title}</span>
            {description && (
              <Tooltip title={description}>
                <QuestionCircleOutlined style={{ color: '#999', cursor: 'pointer' }} />
              </Tooltip>
            )}
          </Space>
          <Form.Item
            name={[name, 'enabled']}
            valuePropName="checked"
            noStyle
          >
            <Switch
              checkedChildren="开启"
              unCheckedChildren="关闭"
            />
          </Form.Item>
        </div>

        {/* 推送渠道 */}
        <Form.Item
          label="推送渠道"
          style={{ marginBottom: 0 }}
        >
          <Space size="large">
            <Form.Item
              name={[name, 'channels', 'sms']}
              valuePropName="checked"
              noStyle
            >
              <Checkbox>短信</Checkbox>
            </Form.Item>
            <Form.Item
              name={[name, 'channels', 'wechat']}
              valuePropName="checked"
              noStyle
            >
              <Checkbox>公众号</Checkbox>
            </Form.Item>
            <Form.Item
              name={[name, 'channels', 'both']}
              valuePropName="checked"
              noStyle
            >
              <Checkbox>两者都发</Checkbox>
            </Form.Item>
          </Space>
        </Form.Item>

        {/* 模板内容 */}
        <Form.Item
          label="模板内容"
          name={[name, 'template']}
          style={{ marginBottom: 0 }}
        >
          <TextArea
            rows={3}
            placeholder="请输入模板内容"
            style={{ fontSize: 13 }}
          />
        </Form.Item>
      </div>
    </Card>
  )

  return (
    <PageContainer
      header={{
        title: (
          <Space>
            <BellOutlined style={{ color: '#1890ff' }} />
            <span style={{ fontSize: 20, fontWeight: 600 }}>通知配置</span>
          </Space>
        ),
        breadcrumb: undefined,
      }}
    >
      <Form
        form={form}
        layout="vertical"
        initialValues={initialValues}
      >
        <Space direction="vertical" size="middle" style={{ width: '100%' }}>
          {/* 存件成功通知 */}
          <NotificationItem
            name="depositSuccess"
            icon={<InboxOutlined />}
            title="存件成功通知"
            color="#2563EB"
            description="用户存件成功后发送的通知"
          />

          {/* 取件提醒 */}
          <NotificationItem
            name="pickupReminder"
            icon={<CheckCircleOutlined />}
            title="取件提醒"
            color="#10B981"
            description="物品存放一段时间后提醒用户取件"
          />

          {/* 超期提醒 */}
          <NotificationItem
            name="overdueReminder"
            icon={<ClockCircleOutlined />}
            title="超期提醒"
            color="#F59E0B"
            description="物品超期后的提醒通知"
          />

          {/* 滞留提醒 */}
          <NotificationItem
            name="retentionReminder"
            icon={<BoxPlotOutlined />}
            title="滞留提醒"
            color="#EF4444"
            description="物品长期滞留后的提醒"
          />

          {/* 设备告警通知 */}
          <NotificationItem
            name="deviceAlarm"
            icon={<WarningOutlined />}
            title="设备告警通知"
            color="#EF4444"
            description="设备发生异常时发送告警通知"
          />

          {/* 认证结果通知 */}
          <NotificationItem
            name="authResult"
            icon={<UserOutlined />}
            title="认证结果通知"
            color="#8B5CF6"
            description="用户认证审核结果通知"
          />

          {/* 积分到账通知 */}
          <NotificationItem
            name="pointsCredit"
            icon={<GiftOutlined />}
            title="积分到账通知"
            color="#F59E0B"
            description="积分发放后的到账通知"
          />

          {/* 积分过期提醒 */}
          <NotificationItem
            name="pointsExpire"
            icon={<FileTextOutlined />}
            title="积分过期提醒"
            color="#EF4444"
            description="积分即将过期的提醒通知"
          />

          {/* 保存按钮 */}
          <div style={{ display: 'flex', justifyContent: 'center', padding: '20px 0' }}>
            <Button
              type="primary"
              icon={<SaveOutlined />}
              onClick={handleSave}
              loading={saving}
              size="large"
              style={{ minWidth: 200 }}
            >
              保存配置
            </Button>
          </div>
        </Space>
      </Form>
    </PageContainer>
  )
}

export default Notification